      "name": "How long does a Toyota hybrid battery last before it needs replacement?",
      "acceptedAnswer": {
        "@type": "Answer",
        "text": "Most Toyota hybrid batteries last between 8 to 10 years or 100,000 to 150,000 miles, depending on maintenance and driving habits."
      }
    },
